231	        private static DataSet GetAdminData(
232	            string connString, string flag, string serverName)
233	        {
234	            using var con = new SqlConnection(connString);
235	            using var cmd = new SqlCommand("OCR_AI_ENABLED_COUNT", con)
236	            {
237	                CommandType = CommandType.StoredProcedure,
238	                CommandTimeout = 120
239	            };
240	
241	            cmd.Parameters.AddWithValue("@MFLAG", flag);
242	            cmd.Parameters.AddWithValue("@serverName", serverName);
243	
244	            var errParam = new SqlParameter("@ERRORMSG",
245	                System.Data.SqlDbType.NVarChar, -1)
246	            { Direction = ParameterDirection.Output };
247	            cmd.Parameters.Add(errParam);
248	
249	            var adapter = new SqlDataAdapter(cmd);
250	            var ds = new DataSet();
251	            adapter.Fill(ds);
252	
253	            string errMsg = errParam.Value?.ToString();
254	            if (!string.IsNullOrEmpty(errMsg))
255	                Logger.Warn("Admin SP Error [{0}]: {1}", serverName, errMsg);
256	
257	            return ds;
258	        }
