263	        private static DataTable GetClientData(
264	            string connStr,
265	            string flag,
266	            string serverName,
267	            string workingPeriod,
268	            string companyLicense,
269	            string companyName,
270	            string enabledDate,
271	            string disabledDate)
272	        {
273	            try
274	            {
275	                using var conn = new SqlConnection(connStr);
276	                using var cmd = new SqlCommand("OCR_AI_JOB_COUNT", conn)
277	                {
278	                    CommandType = CommandType.StoredProcedure,
279	                    CommandTimeout = 180
280	                };
281	
282	                cmd.Parameters.AddWithValue("@MFLAG", flag);
283	                cmd.Parameters.AddWithValue("@Server_name", serverName);
284	                cmd.Parameters.AddWithValue("@WORKING_PERIOD", workingPeriod);
285	                cmd.Parameters.AddWithValue("@COMPANY_LICENSE", companyLicense);
286	                cmd.Parameters.AddWithValue("@COMPANY_NAME", companyName);
287	                cmd.Parameters.AddWithValue("@ENABLED_DATE", enabledDate);
288	                cmd.Parameters.AddWithValue("@DISABLED_DATE", disabledDate);
289	
290	                var errParam = new SqlParameter("@ERRORMSG",
291	                    System.Data.SqlDbType.NVarChar, -1)
292	                { Direction = ParameterDirection.Output };
293	                cmd.Parameters.Add(errParam);
294	
295	                var adapter = new SqlDataAdapter(cmd);
296	                var ds = new DataSet();
297	                adapter.Fill(ds);
298	
299	                string errMsg = errParam.Value?.ToString();
300	                if (!string.IsNullOrEmpty(errMsg))
301	                    Logger.Warn("Client SP Error [{0}][{1}][{2}]: {3}",
302	                        serverName, companyLicense, flag, errMsg);
303	
304	                // JOB_COUNT uses EXEC(@sql) with SET NOCOUNT ON
305	                // → result lands in Tables[0] (no PRINT statement)
306	                return ds.Tables.Count > 0 ? ds.Tables[0] : new DataTable();
307	            }
308	            catch (Exception ex)
309	            {
310	                Logger.Error(ex, "GetClientData failed [{0}][{1}][{2}]",
311	                    serverName, companyLicense, flag);
312	                return new DataTable();
313	            }
314	        }
