333	                    cell.Style.Alignment.Horizontal =
334	                        XLAlignmentHorizontalValues.Center;
335	                }
336	                currentRow++;
337	            }
338	
339	            foreach (DataRow row in table.Rows)
340	            {
341	                for (int col = 0; col < table.Columns.Count; col++)
342	                    ws.Cell(currentRow, col + 1).Value = row[col]?.ToString();
343	
344	                if (currentRow % 2 == 0)
345	                    ws.Range(currentRow, 1, currentRow, table.Columns.Count)
346	                      .Style.Fill.BackgroundColor = XLColor.LightGray;
347	
348	                currentRow++;
349	            }
