396	        private static string ParseDateToYMD(string dateStr)
397	        {
398	            if (string.IsNullOrWhiteSpace(dateStr)) return "";
399	            try
400	            {
401	                return DateTime.ParseExact(dateStr.Trim(), "dd-MM-yyyy", null)
402	                               .ToString("yyyy-MM-dd");
403	            }
404	            catch
405	            {
406	                Logger.Warn("Could not parse date: {0}", dateStr);
407	                return dateStr;
