412	        // Send email with Excel attachment
413	        // ─────────────────────────────────────────────────────────────────────
414	        private static async Task SendEmailWithAttachment(string filePath)
415	        {
416	            try
417	            {
418	                Logger.Info("Sending email...");
419	
420	                string reportDate = DateTime.Now.AddDays(-1).ToString("dd-MM-yyyy");
421	                string subject = _smtpSettings.Subject.Replace("{Date}", reportDate);
422	                string htmlBody = _smtpSettings.Body.Replace("{Date}", reportDate);
423	
424	                using var mail = new MailMessage
425	                {
426	                    From = new MailAddress(
427	                                     _smtpSettings.FromEmail,
428	                                     _smtpSettings.Mail_header),
429	                    Subject = subject,
430	                    IsBodyHtml = true
431	                };
432	
433	                string logoPath = Path.Combine(
434	                    AppContext.BaseDirectory, "Assets", "Company_Logo.png");
435	
436	                if (File.Exists(logoPath))
437	                {
438	                    var htmlView = AlternateView.CreateAlternateViewFromString(
439	                        htmlBody, null, "text/html");
440	                    var logoRes = new LinkedResource(logoPath, "image/png")
441	                    { ContentId = "companylogo" };
442	                    htmlView.LinkedResources.Add(logoRes);
443	                    mail.AlternateViews.Add(htmlView);
444	                }
445	                else
446	                {
447	                    Logger.Warn("Logo not found at {0}; sending without logo", logoPath);
448	                    mail.Body = htmlBody;
449	                }
450	
451	                foreach (var to in (_smtpSettings.ToEmails ?? Array.Empty<string>()))
452	                    mail.To.Add(to.Trim());
453	
454	                foreach (var cc in (_smtpSettings.CCEmails ?? Array.Empty<string>()))
455	                    mail.CC.Add(cc.Trim());
456	
457	                using (var fs = new FileStream(
458	                    filePath, FileMode.Open, FileAccess.Read, FileShare.Read))
459	                {
460	                    mail.Attachments.Add(new Attachment(fs, Path.GetFileName(filePath)));
461	
462	                    using var smtp = new SmtpClient(
463	                        _smtpSettings.Host, _smtpSettings.SmtpPort)
464	                    {
465	                        Credentials = new NetworkCredential(
466	                            _smtpSettings.username, _smtpSettings.password),
467	                        EnableSsl = _smtpSettings.enableSsl
468	                    };
469	                    await smtp.SendMailAsync(mail);
470	                }
471	
472	                Logger.Info("Email sent: {0}", Path.GetFileName(filePath));
473	
474	                if (File.Exists(filePath))
475	                {
476	                    File.Delete(filePath);
477	                    Logger.Info("Deleted report: {0}", filePath);
478	                }
479	            }
480	            catch (Exception ex)
481	            {
482	                Logger.Error(ex, "Email send failed");
483	            }
484	        }
485	    }
